const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const openjpeg_src = b.dependency("openjpeg_src", .{});

    // Create static library
    const lib = b.addLibrary(.{
        .name = "openjp2",
        .linkage = .static,
        .root_module = b.createModule(.{
            .target = target,
            .optimize = optimize,
            .link_libc = true,
        }),
    });

    // Generate config headers
    const opj_config_h = b.addWriteFiles();
    _ = opj_config_h.add("opj_config.h",
        \\/* OpenJPEG configuration - generated by Zig build */
        \\#ifndef OPJ_CONFIG_H
        \\#define OPJ_CONFIG_H
        \\
        \\#define OPJ_VERSION_MAJOR 2
        \\#define OPJ_VERSION_MINOR 5
        \\#define OPJ_VERSION_BUILD 4
        \\
        \\/* Threading support */
        \\#define OPJ_HAVE_STDINT_H 1
        \\#define OPJ_HAVE_INTTYPES_H 1
        \\
        \\#endif /* OPJ_CONFIG_H */
    );

    // Platform-specific configuration
    const is_windows = target.result.os.tag == .windows;

    if (is_windows) {
        _ = opj_config_h.add("opj_config_private.h",
            \\/* OpenJPEG private configuration - generated by Zig build (Windows) */
            \\#ifndef OPJ_CONFIG_PRIVATE_H
            \\#define OPJ_CONFIG_PRIVATE_H
            \\
            \\/* For internal use only */
            \\#define OPJ_PACKAGE_VERSION "2.5.4"
            \\
            \\/* Windows uses _aligned_malloc */
            \\#define OPJ_HAVE_ALIGNED_ALLOC 1
            \\#define OPJ_HAVE__ALIGNED_MALLOC 1
            \\
            \\/* TLS support */
            \\#define OPJ_HAVE_TLS 1
            \\
            \\#endif /* OPJ_CONFIG_PRIVATE_H */
        );
    } else {
        _ = opj_config_h.add("opj_config_private.h",
            \\/* OpenJPEG private configuration - generated by Zig build (POSIX) */
            \\#ifndef OPJ_CONFIG_PRIVATE_H
            \\#define OPJ_CONFIG_PRIVATE_H
            \\
            \\/* For internal use only */
            \\#define OPJ_PACKAGE_VERSION "2.5.4"
            \\
            \\/* Large file support */
            \\#define OPJ_HAVE_FSEEKO 1
            \\
            \\/* Memory aligned malloc */
            \\#define OPJ_HAVE_POSIX_MEMALIGN 1
            \\
            \\/* Threading - use standard threads on POSIX */
            \\#define OPJ_HAVE_PTHREAD_H 1
            \\#define OPJ_USE_THREAD 1
            \\
            \\/* TLS support */
            \\#if defined(__GNUC__) || defined(__clang__)
            \\#define OPJ_HAVE_TLS 1
            \\#endif
            \\
            \\#endif /* OPJ_CONFIG_PRIVATE_H */
        );
    }

    // C flags
    const cflags: []const []const u8 = &.{
        "-DOPJ_STATIC",
        "-fvisibility=hidden",
        // Upstream OpenJPEG's UB, not ours. openjpeg.c:225 and :336 store
        // `opj_j2k_setup_decoder` (which takes `opj_j2k_t *`) into a function
        // pointer typed `void (*)(void *, opj_dparameters_t *)` and then call
        // through it. Calling through an incompatible function-pointer type is
        // undefined (C17 §6.3.2.3p8), and clang's `-fsanitize=function` — on
        // by default for C that Zig compiles in Debug/ReleaseSafe — traps it
        // with `ud1`. Zig's segfault handler catches the SIGILL and aborts.
        //
        // It only bites on "vendored openjpeg + Debug/ReleaseSafe", which is
        // exactly what a dev running `zig build test` in the devShell gets:
        // the Nix path links the system libopenjp2 (gcc-built, uninstrumented)
        // and cross-compiles run ReleaseFast where the sanitizer is off. So it
        // sat latent, five SIGABRTs deep in decode_jp2, while every gate
        // stayed green. Diagnosed by jp2z from a coredump disassembly
        // (2026-08-13) and reproduced here.
        //
        // Disabling this ONE check on third-party C is the right scope —
        // patching the casts would fork us from upstream, and the rest of
        // UBSan stays active.
        "-fno-sanitize=function",
    };

    // Source files for openjp2 library
    const openjp2_sources: []const []const u8 = &.{
        "src/lib/openjp2/thread.c",
        "src/lib/openjp2/bio.c",
        "src/lib/openjp2/cio.c",
        "src/lib/openjp2/dwt.c",
        "src/lib/openjp2/event.c",
        "src/lib/openjp2/ht_dec.c",
        "src/lib/openjp2/image.c",
        "src/lib/openjp2/invert.c",
        "src/lib/openjp2/j2k.c",
        "src/lib/openjp2/jp2.c",
        "src/lib/openjp2/mct.c",
        "src/lib/openjp2/mqc.c",
        "src/lib/openjp2/openjpeg.c",
        "src/lib/openjp2/opj_clock.c",
        "src/lib/openjp2/pi.c",
        "src/lib/openjp2/t1.c",
        "src/lib/openjp2/t2.c",
        "src/lib/openjp2/tcd.c",
        "src/lib/openjp2/tgt.c",
        "src/lib/openjp2/function_list.c",
        "src/lib/openjp2/opj_malloc.c",
        "src/lib/openjp2/sparse_array.c",
    };

    lib.root_module.addCSourceFiles(.{
        .root = openjpeg_src.path(""),
        .files = openjp2_sources,
        .flags = cflags,
    });

    // Include paths
    lib.root_module.addIncludePath(openjpeg_src.path("src/lib/openjp2"));
    lib.root_module.addIncludePath(opj_config_h.getDirectory());

    // Install headers for consumers
    lib.installHeader(openjpeg_src.path("src/lib/openjp2/openjpeg.h"), "openjpeg.h");

    // Also install the generated config header
    lib.root_module.addIncludePath(opj_config_h.getDirectory());
    lib.installHeadersDirectory(opj_config_h.getDirectory(), "", .{
        .include_extensions = &.{".h"},
    });

    b.installArtifact(lib);
}
